class ModuleUtilLocatorBase:
    \"\"\"Resolve one import without executing module_utils code on the controller.\"\"\"

    prefix_length = 0
    redirect_first = False

    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False):
        self.fq_name_parts = tuple(fq_name_parts)
        self.is_ambiguous = is_ambiguous and len(self.fq_name_parts) > self.prefix_length + 1
        self.child_is_redirected = child_is_redirected
        self.found = False
        self.redirected = False
        self.pkg_dir = False
        self.py_src = True
        self.name_parts = None
        self.output_path = None
        self.source = None
        self.path = None
        self.redirect_target = None

    def candidate_names_joined(self):
        candidates = [self.fq_name_parts]
        if self.is_ambiguous:
            candidates.append(self.fq_name_parts[:-1])
        return ['.'.join(parts) for parts in candidates]

    def _routing(self, parts):
        return None

    def _local(self, parts):
        return None

    def locate(self):
        candidates = [self.fq_name_parts]
        if self.is_ambiguous:
            candidates.append(self.fq_name_parts[:-1])
        for parts in candidates:
            checks = (self._routing, self._local) if self.redirect_first else (self._local, self._routing)
            for check in checks:
                result = check(parts)
                if result is None:
                    continue
                source, path, package, target = result
                self.found = True
                self.name_parts = parts
                self.pkg_dir = package
                self.redirected = target is not None
                self.redirect_target = target
                self.source = source
                self.path = path
                self.output_path = os.path.join(*(parts + (('__init__',) if package else ()))) + '.py'
                return self
        return self


def _redirect_source(original, target):
    return to_bytes(\"import sys\\nimport {0} as mod\\nsys.modules[{1"'!r}] = mod'"\\n\".format(target, original))


def _routing_result(parts, collection, entry):
    if not entry:
        return None
    deprecated = entry.get('deprecation')
    if deprecated:
        display.deprecated(deprecated.get('warning_text') or '%s has been deprecated' % '.'.join(parts),
                           version=deprecated.get('removal_version'), date=deprecated.get('removal_date'),
                           collection_name=collection)
    tombstone = entry.get('tombstone')
    if tombstone:
        raise AnsibleError(display.get_deprecation_message(
            tombstone.get('warning_text') or '%s has been removed' % '.'.join(parts),
            version=tombstone.get('removal_version'), date=tombstone.get('removal_date'),
            removed=True, collection_name=collection))
    target = entry.get('redirect')
    if not target:
        return None
    if not target.startswith(('ansible_collections.', 'ansible.module_utils.')):
        target_parts = target.split('.')
        if len(target_parts) < 3:
            raise AnsibleError('Invalid module_utils redirect %s' % target)
        target = '.'.join(('ansible_collections',) + tuple(target_parts[:2]) +
                          ('plugins', 'module_utils') + tuple(target_parts[2:]))
    return _redirect_source('.'.join(parts), target), '<redirect>', False, target


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 2

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)
        self.mu_paths = mu_paths if mu_paths is not None else [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]

    def _local(self, parts):
        relative = parts[2:]
        if not relative:
            return None
        try:
            info = ModuleInfo(relative[-1], [os.path.join(p, *relative[:-1]) for p in self.mu_paths])
        except ImportError:
            return None
        if not info.pkg_dir and not info.py_src:
            raise AnsibleError('Could not find python source for imported module support code for %s' % '.'.join(parts))
        return info.get_source(), info.path, info.pkg_dir, None

    def _routing(self, parts):
        key = '.'.join(parts[2:])
        metadata = _get_collection_metadata('ansible.builtin')
        return _routing_result(parts, 'ansible.builtin', metadata.get('plugin_routing', {}).get('module_utils', {}).get(key))


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 5
    redirect_first = True

    def _metadata(self, parts):
        collection = '.'.join(parts[1:3])
        try:
            return collection, _get_collection_metadata(collection)
        except ValueError as exc:
            raise AnsibleError(to_native(exc))

    def _routing(self, parts):
        collection, metadata = self._metadata(parts)
        key = '.'.join(parts[5:])
        return _routing_result(parts, collection, metadata.get('plugin_routing', {}).get('module_utils', {}).get(key))

    def _local(self, parts):
        collection, unused = self._metadata(parts)
        package = __import__('ansible_collections.' + collection, fromlist=['__path__'])
        relative = os.path.join(*parts[3:]) if len(parts) > 3 else ''
        for root in package.__path__:
            base = os.path.join(root, relative)
            for candidate, is_package in ((os.path.join(base, '__init__.py'), True), (base + '.py', False)):
                if os.path.isfile(candidate):
                    return _slurp(candidate), candidate, is_package, None
            if os.path.isdir(base):
                return b'', '<synthetic package>', True, None
        return None


def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    \"\"\"Collect module_utils and their dependencies in a queue.\"\"\"
    from collections import deque

    mu_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
    mu_paths.append(_MODULE_UTILS_PATH)
    pending = deque([(name, module_fqn, data)])
    queued = set(py_module_names)
    # The wrapper always needs basic, even when the module does not import it.
    pending_imports = deque([(('ansible', 'module_utils', 'basic'), False)])
    for base_name, base_source in ((('ansible', '__init__'), b'from pkgutil import extend_path\\n__path__=extend_path(__path__,__name__)\\n'),
                                   (('ansible', 'module_utils', '__init__'), b'from pkgutil import extend_path\\n__path__=extend_path(__path__,__name__)\\n')):
        path = '/'.join(base_name) + '.py'
        if path not in zf.namelist():
            zf.writestr(path, base_source)
        py_module_names.add(base_name)
        queued.add(base_name)

    while pending or pending_imports:
        if pending:
            current_name, current_fqn, current_data = pending.popleft()
            try:
                tree = compile(current_data, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
            except (SyntaxError, IndentationError) as exc:
                raise AnsibleError('Unable to import %s due to %s' % (current_name, exc.msg))
            finder = ModuleDepFinder(current_fqn)
            finder.visit(tree)
            for imported in sorted(finder.submodules):
                pending_imports.append((imported, True))
            continue

        imported, ambiguous = pending_imports.popleft()
        if imported[:3] == ('ansible', 'module_utils', 'six'):
            imported = imported[:3]
            ambiguous = False
        elif imported[:2] == ('ansible', 'module_utils') and imported[2:3] == ('_six',):
            imported = ('ansible', 'module_utils', 'six', '_six')
            ambiguous = False
        if imported[:2] == ('ansible', 'module_utils'):
            locator = LegacyModuleUtilLocator(imported, ambiguous, mu_paths)
        elif imported[:1] == ('ansible_collections',) and len(imported) >= 5 and imported[3:5] == ('plugins', 'module_utils'):
            locator = CollectionModuleUtilLocator(imported, ambiguous)
        else:
            continue
        if imported in queued or imported + ('__init__',) in queued:
            continue
        locator.locate()
        if not locator.found:
            raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                               (module_fqn, ', '.join(locator.candidate_names_joined())))
        parts = locator.name_parts
        normalized = parts + (('__init__',) if locator.pkg_dir else ())
        if normalized not in queued:
            queued.add(normalized)
            py_module_names.add(normalized)
            zf.writestr(locator.output_path, locator.source)
            display.vvvvv('Using module_utils file %s' % locator.path)
            pending.append((parts[-1], '.'.join(normalized), locator.source))
        for length in range(1, len(parts)):
            parent = parts[:length]
            if parent in (('ansible',), ('ansible', 'module_utils')):
                continue
            if parent[0] == 'ansible' and length < 3:
                continue
            pkg_name = parent + ('__init__',)
            if pkg_name in queued:
                continue
            if parent[0] == 'ansible_collections':
                if length > 5:
                    parent_locator = CollectionModuleUtilLocator(parent).locate()
                    pkg_source = parent_locator.source if parent_locator.found and parent_locator.pkg_dir else b''
                else:
                    pkg_source = b''
            else:
                parent_locator = LegacyModuleUtilLocator(parent, mu_paths=mu_paths).locate()
                pkg_source = parent_locator.source if parent_locator.found and parent_locator.pkg_dir else b''
            queued.add(pkg_name)
            py_module_names.add(pkg_name)
            zf.writestr('/'.join(pkg_name) + '.py', pkg_source)
            pending.append((parent[-1], '.'.join(pkg_name), pkg_source))
EOF
